using Commerce;

namespace Commerce.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem Tests ---

    [TestMethod]
    public void AddItem_SingleItem_IncludedInTotal()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        Assert.AreEqual(10.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleQuantity_MultipliesPrice()
    {
        _cart.AddItem("SKU1", 5.00m, 3);
        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleItems_SumsAll()
    {
        _cart.AddItem("SKU1", 10.00m, 2);
        _cart.AddItem("SKU2", 7.50m, 1);
        Assert.AreEqual(27.50m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_BothCounted()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        _cart.AddItem("SKU1", 10.00m, 1);
        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    // --- RemoveItem Tests ---

    [TestMethod]
    public void RemoveItem_ExistingItem_ReturnsTrue()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        Assert.IsTrue(_cart.RemoveItem("SKU1"));
    }

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromTotal()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        _cart.AddItem("SKU2", 5.00m, 2);
        _cart.RemoveItem("SKU1");
        Assert.AreEqual(10.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistingItem_ReturnsFalse()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        Assert.IsFalse(_cart.RemoveItem("UNKNOWN"));
    }

    [TestMethod]
    public void RemoveItem_DuplicateSku_RemovesAll()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        _cart.AddItem("SKU1", 10.00m, 1);
        _cart.RemoveItem("SKU1");
        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    // --- GetTotal Tests ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_AfterRemovingAllItems_ReturnsZero()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        _cart.RemoveItem("SKU1");
        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    // --- ApplyPromoCode Tests ---

    [TestMethod]
    public void ApplyPromoCode_ValidCode_ReturnsTrue()
    {
        Assert.IsTrue(_cart.ApplyPromoCode("SAVE10"));
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_ReturnsFalse()
    {
        Assert.IsFalse(_cart.ApplyPromoCode("BOGUS"));
    }

    [TestMethod]
    public void ApplyPromoCode_Save10_Applies10PercentDiscount()
    {
        _cart.AddItem("SKU1", 100.00m, 1);
        _cart.ApplyPromoCode("SAVE10");
        Assert.AreEqual(90.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_Save20_Applies20PercentDiscount()
    {
        _cart.AddItem("SKU1", 50.00m, 2);
        _cart.ApplyPromoCode("SAVE20");
        Assert.AreEqual(80.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_Half_Applies50PercentDiscount()
    {
        _cart.AddItem("SKU1", 40.00m, 1);
        _cart.ApplyPromoCode("HALF");
        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_NoDiscountApplied()
    {
        _cart.AddItem("SKU1", 100.00m, 1);
        _cart.ApplyPromoCode("BOGUS");
        Assert.AreEqual(100.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_AppliedToEmptyCart_TotalRemainsZero()
    {
        _cart.ApplyPromoCode("SAVE10");
        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_SecondCodeOverridesFirst()
    {
        _cart.AddItem("SKU1", 100.00m, 1);
        _cart.ApplyPromoCode("SAVE10");
        _cart.ApplyPromoCode("SAVE20");
        Assert.AreEqual(80.00m, _cart.GetTotal());
    }
}

